const TREND_TEXT: Record<Career['trend'], string> = {
  up: '赛道整体在扩张，当下入场时机不错，值得认真投入。',
  stable: '赛道稳定，拼的是长期积累和差异化定位。',
  down: '赛道整体收缩，入行需谨慎，或把它当作积累可迁移能力的跳板。',
};

/** AI 建议：由职业自身字段（核心技能/AI 风险/趋势）动态生成，每个职业文案不同 */
export function getAiAdvice(c: Career): string {
  return `${c.name}的核心竞争力在于${c.keySkill}。${AI_RISK_TEXT[c.aiRisk]}${TREND_TEXT[c.trend]}建议先小成本试错验证匹配度——做一个小项目、一次实习或跟从业者聊一个月——再决定是否长期投入。`;
}

export function defaultSelfStudyScore(difficulty: 'easy' | 'medium' | 'hard'): number {
  return difficulty === 'easy' ? 9 : difficulty === 'medium' ? 6 : 3;
}

